import React, { useEffect, useState } from 'react';
import {
  Elements,
  PaymentElement,
  useElements,
  useStripe,
} from '@stripe/react-stripe-js';
import { loadStripe, type Stripe } from '@stripe/stripe-js';
import {
  ArrowLeft,
  ArrowRight,
  Check,
  CreditCard,
  Loader2,
  Lock,
  Mail,
  ShieldCheck,
  UserRound,
} from 'lucide-react';
import { motion } from 'motion/react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import { SEO } from '@/components/SEO';
import {
  communitySubscriptionAction,
  communitySubscriptionPath,
  formatCommunitySubscriptionPrice,
  type CommunitySubscriptionPublicPlan,
} from '@/lib/communitySubscriptions';
import { invokeApiRunner, supabase } from '@/lib/supabase';

type CheckoutResponse = {
  checkoutId: string;
  subscriptionId: string;
  stripeAccountId: string;
  clientSecret: string | null;
  status: string;
};

const PaymentForm = ({
  checkoutId,
  returnPath,
  ctaLabel,
  accentColor,
  onBack,
}: {
  checkoutId: string;
  returnPath: string;
  ctaLabel: string;
  accentColor: string;
  onBack: () => void;
}) => {
  const stripe = useStripe();
  const elements = useElements();
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!stripe || !elements || submitting) return;
    setError('');
    setSubmitting(true);
    try {
      const validation = await elements.submit();
      if (validation.error) {
        setError(validation.error.message || 'Check your payment details.');
        return;
      }
      const returnUrl = new URL('/payment-success', window.location.origin);
      returnUrl.searchParams.set('source', 'community-subscription');
      returnUrl.searchParams.set('checkout_id', checkoutId);
      returnUrl.searchParams.set('status', 'processing');
      returnUrl.searchParams.set('return_to', returnPath);
      const confirmation = await stripe.confirmPayment({
        elements,
        confirmParams: { return_url: returnUrl.toString() },
      });
      if (confirmation.error) {
        setError(confirmation.error.message || 'The payment could not be completed.');
      }
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : 'The payment could not be completed.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={submit}>
      <div className="mb-7 flex items-start justify-between gap-4">
        <div>
          <p className="text-[10px] font-black uppercase tracking-[0.22em] text-white/35">Secure checkout</p>
          <h2 className="mt-2 text-2xl font-black tracking-tight text-white">Choose how to pay</h2>
        </div>
        <button type="button" onClick={onBack} className="rounded-full border border-white/10 px-4 py-2 text-xs font-bold text-white/55 transition hover:bg-white/[0.06] hover:text-white">
          Edit details
        </button>
      </div>
      <div className="rounded-[22px] bg-white p-4 sm:p-5">
        <PaymentElement options={{ layout: { type: 'accordion', defaultCollapsed: false, radios: true, spacedAccordionItems: true } }} />
      </div>
      {error && <div role="alert" className="mt-5 rounded-2xl border border-rose-400/20 bg-rose-400/10 px-4 py-3 text-sm leading-6 text-rose-100">{error}</div>}
      <button
        type="submit"
        disabled={!stripe || !elements || submitting}
        style={{ backgroundColor: accentColor }}
        className="mt-6 flex min-h-14 w-full items-center justify-center gap-2 rounded-2xl px-6 text-sm font-black text-white shadow-lg transition hover:brightness-110 disabled:cursor-not-allowed disabled:opacity-50"
      >
        {submitting ? <><Loader2 className="h-4 w-4 animate-spin" /> Confirming securely</> : <>{ctaLabel}<ArrowRight className="h-4 w-4" /></>}
      </button>
      <p className="mt-4 flex items-center justify-center gap-2 text-center text-xs text-white/35"><Lock className="h-3.5 w-3.5" /> Payment details are handled securely by Stripe.</p>
    </form>
  );
};

export const CommunitySubscriptionPayPage = () => {
  const navigate = useNavigate();
  const { communityId = '', slug = '' } = useParams();
  const [plan, setPlan] = useState<CommunitySubscriptionPublicPlan | null>(null);
  const [user, setUser] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [pageError, setPageError] = useState('');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [creating, setCreating] = useState(false);
  const [clientSecret, setClientSecret] = useState('');
  const [checkoutId, setCheckoutId] = useState('');
  const [stripePromise, setStripePromise] = useState<Promise<Stripe | null> | null>(null);
  const [requestId] = useState(() => crypto.randomUUID());
  const returnPath = communitySubscriptionPath(communityId, slug);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      setPageError('');
      try {
        const [{ plan: publicPlan }, auth] = await Promise.all([
          communitySubscriptionAction<{ plan: CommunitySubscriptionPublicPlan }>('public_plan', { communityId, slug }),
          supabase.auth.getUser(),
        ]);
        if (cancelled) return;
        setPlan(publicPlan);
        setUser(auth.data.user || null);
        setEmail(auth.data.user?.email || '');
        setName(String(auth.data.user?.user_metadata?.full_name || auth.data.user?.user_metadata?.name || '').trim());
      } catch (reason) {
        if (!cancelled) setPageError(reason instanceof Error ? reason.message : 'This membership is not available.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void load();
    return () => { cancelled = true; };
  }, [communityId, slug]);

  const continueToPayment = async (event: React.FormEvent) => {
    event.preventDefault();
    setPageError('');
    if (!user) {
      navigate(`/auth?redirect=${encodeURIComponent(returnPath)}`);
      return;
    }
    if (!plan) return;
    if (name.trim().length < 2) {
      setPageError('Enter your full name.');
      return;
    }
    setCreating(true);
    try {
      const [config, checkout] = await Promise.all([
        invokeApiRunner('stripe-config', {}, 1, 800),
        communitySubscriptionAction<CheckoutResponse>('create_checkout', {
          tierId: plan.id,
          requestId,
          name: name.trim(),
          email,
        }),
      ]);
      const publishableKey = typeof config?.publishableKey === 'string' ? config.publishableKey.trim() : '';
      if (!publishableKey) throw new Error('Secure payments are temporarily unavailable.');
      if (!checkout.clientSecret) {
        navigate(`/payment-success?source=community-subscription&checkout_id=${encodeURIComponent(checkout.checkoutId)}&status=processing&return_to=${encodeURIComponent(returnPath)}`);
        return;
      }
      setCheckoutId(checkout.checkoutId);
      setClientSecret(checkout.clientSecret);
      setStripePromise(loadStripe(publishableKey, { stripeAccount: checkout.stripeAccountId }));
    } catch (reason) {
      const message = reason instanceof Error ? reason.message : 'Secure subscription checkout is temporarily unavailable.';
      setPageError(message.includes('FunctionsHttpError') ? 'Secure subscription checkout is temporarily unavailable.' : message);
    } finally {
      setCreating(false);
    }
  };

  if (loading) return <div className="grid min-h-[100dvh] place-items-center bg-[#070708] text-white"><Loader2 className="h-7 w-7 animate-spin text-white/55" /></div>;

  if (!plan) {
    return (
      <div className="grid min-h-[100dvh] place-items-center bg-[#070708] px-5 text-white">
        <div className="max-w-md text-center">
          <h1 className="text-3xl font-black">Membership unavailable</h1>
          <p className="mt-3 leading-7 text-white/50">{pageError || 'This membership is no longer available.'}</p>
          <button type="button" onClick={() => navigate(`/community/${encodeURIComponent(communityId)}`)} className="mt-7 rounded-2xl bg-white px-6 py-3 font-black text-black">Back to community</button>
        </div>
      </div>
    );
  }

  const page = plan.pageConfig;
  const image = page.coverImageUrl || plan.community.bannerUrl || plan.community.logoUrl || undefined;
  return (
    <div className="relative min-h-[100dvh] overflow-hidden bg-[#070708] text-white">
      <SEO title={`${plan.name} — ${plan.community.name}`} description={page.subheadline} image={image} url={returnPath} type="product" />
      <div className="pointer-events-none absolute -left-44 -top-52 h-[620px] w-[620px] rounded-full opacity-20 blur-[160px]" style={{ backgroundColor: page.accentColor }} />
      <div className="pointer-events-none absolute -bottom-64 right-0 h-[560px] w-[560px] rounded-full bg-white/[0.035] blur-[150px]" />
      <header className="relative z-10 mx-auto flex w-full max-w-7xl items-center justify-between px-5 py-5 sm:px-8">
        <Link to={`/community/${encodeURIComponent(plan.community.id)}`} className="inline-flex items-center gap-2 text-sm font-bold text-white/55 transition hover:text-white"><ArrowLeft className="h-4 w-4" /> Back to {plan.community.name}</Link>
        <div className="text-base font-black tracking-tight">Wersee</div>
      </header>

      <main className="relative z-10 mx-auto grid min-h-[calc(100dvh-76px)] w-full max-w-7xl items-center gap-10 px-5 py-8 sm:px-8 lg:grid-cols-[minmax(0,1.05fr)_minmax(440px,0.95fr)] lg:gap-16 lg:py-12">
        <section className="max-w-2xl">
          {image && <div className="mb-8 h-48 overflow-hidden rounded-[32px] border border-white/10 sm:h-60"><img src={image} alt="" className="h-full w-full object-cover opacity-75" referrerPolicy="no-referrer" /></div>}
          <div className="flex items-center gap-3">
            {plan.community.logoUrl ? <img src={plan.community.logoUrl} alt="" className="h-11 w-11 rounded-2xl border border-white/10 object-cover" referrerPolicy="no-referrer" /> : <span className="grid h-11 w-11 place-items-center rounded-2xl border border-white/10 bg-white/[0.05] text-sm font-black">{plan.community.name.slice(0, 1).toUpperCase()}</span>}
            <div><p className="text-[10px] font-black uppercase tracking-[0.22em] text-white/35">{page.eyebrow}</p><p className="mt-1 text-sm font-bold text-white/70">{plan.community.name}</p></div>
          </div>
          <h1 className="mt-7 max-w-2xl text-5xl font-black tracking-[-0.055em] sm:text-7xl">{page.headline}</h1>
          <p className="mt-5 max-w-xl text-base leading-7 text-white/52 sm:text-lg">{page.subheadline}</p>
          <div className="mt-8 flex items-end gap-2"><span className="text-4xl font-black tracking-tight sm:text-5xl">{formatCommunitySubscriptionPrice(plan.price, plan.currency)}</span><span className="pb-1 text-sm font-bold text-white/35">/ {plan.interval}</span></div>
          {plan.trialPeriodDays > 0 && <p className="mt-3 text-sm font-bold" style={{ color: page.accentColor }}>{plan.trialPeriodDays}-day free trial, then recurring billing</p>}
          {plan.features.length > 0 && <div className="mt-10"><h2 className="text-sm font-black text-white/75">{page.benefitsTitle}</h2><ul className="mt-4 grid gap-3 sm:grid-cols-2">{plan.features.map((feature) => <li key={feature} className="flex items-start gap-3 text-sm leading-6 text-white/62"><span className="mt-0.5 grid h-5 w-5 shrink-0 place-items-center rounded-full bg-white/10"><Check className="h-3 w-3" /></span>{feature}</li>)}</ul></div>}
        </section>

        <motion.section initial={{ opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} className="rounded-[34px] border border-white/10 bg-[#111113]/95 p-5 shadow-2xl shadow-black/40 backdrop-blur sm:p-8">
          {clientSecret && stripePromise && checkoutId ? (
            <Elements stripe={stripePromise} options={{ clientSecret, appearance: { theme: 'stripe', variables: { colorPrimary: page.accentColor, colorText: '#111111', colorDanger: '#dc2626', borderRadius: '12px', fontFamily: 'Inter, ui-sans-serif, system-ui, sans-serif' } } }}>
              <PaymentForm checkoutId={checkoutId} returnPath={returnPath} ctaLabel={page.ctaLabel} accentColor={page.accentColor} onBack={() => { setClientSecret(''); setCheckoutId(''); setStripePromise(null); }} />
            </Elements>
          ) : (
            <form onSubmit={continueToPayment}>
              <p className="text-[10px] font-black uppercase tracking-[0.22em] text-white/35">Membership checkout</p>
              <h2 className="mt-2 text-2xl font-black tracking-tight">{plan.name}</h2>
              <p className="mt-2 text-sm leading-6 text-white/45">Your membership is linked to your Wersee account so community access can be assigned safely.</p>
              {!user ? (
                <div className="mt-7 rounded-[22px] border border-white/10 bg-white/[0.035] p-5">
                  <p className="text-sm leading-6 text-white/55">Sign in or create an account to continue to secure payment.</p>
                  <button type="submit" style={{ backgroundColor: page.accentColor }} className="mt-5 flex min-h-13 w-full items-center justify-center gap-2 rounded-2xl px-5 text-sm font-black text-white transition hover:brightness-110">Sign in to continue<ArrowRight className="h-4 w-4" /></button>
                </div>
              ) : (
                <div className="mt-7 space-y-4">
                  <label className="block"><span className="mb-2 block text-xs font-bold text-white/55">Full name</span><span className="relative block"><UserRound className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/30" /><input value={name} onChange={(event) => setName(event.target.value)} autoComplete="name" placeholder="Your full name" className="min-h-13 w-full rounded-2xl border border-white/10 bg-white/[0.04] pl-11 pr-4 text-sm text-white outline-none transition placeholder:text-white/25 focus:border-white/25" /></span></label>
                  <label className="block"><span className="mb-2 block text-xs font-bold text-white/55">Verified email</span><span className="relative block"><Mail className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/30" /><input value={email} readOnly className="min-h-13 w-full rounded-2xl border border-white/10 bg-white/[0.025] pl-11 pr-4 text-sm text-white/55 outline-none" /></span></label>
                  <button type="submit" disabled={creating} style={{ backgroundColor: page.accentColor }} className="flex min-h-14 w-full items-center justify-center gap-2 rounded-2xl px-6 text-sm font-black text-white transition hover:brightness-110 disabled:cursor-not-allowed disabled:opacity-50">{creating ? <><Loader2 className="h-4 w-4 animate-spin" />Preparing secure checkout</> : <>{page.ctaLabel}<ArrowRight className="h-4 w-4" /></>}</button>
                </div>
              )}
              {pageError && <div role="alert" className="mt-5 rounded-2xl border border-rose-400/20 bg-rose-400/10 px-4 py-3 text-sm leading-6 text-rose-100">{pageError}</div>}
              <div className="mt-6 grid grid-cols-2 gap-3 text-[11px] text-white/38"><div className="flex items-center gap-2 rounded-2xl border border-white/[0.08] p-3"><ShieldCheck className="h-4 w-4 text-emerald-300" />Account-linked access</div><div className="flex items-center gap-2 rounded-2xl border border-white/[0.08] p-3"><CreditCard className="h-4 w-4 text-blue-300" />Stripe secured</div></div>
              <p className="mt-5 text-center text-[11px] leading-5 text-white/28">{page.footerNote}</p>
            </form>
          )}
        </motion.section>
      </main>
    </div>
  );
};
